inline const char *casefold(uint32_t codepoint) {
  size_t low = 0, high = sizeof(folds) / sizeof(folds[0]);
  while (low < high) {
    const size_t mid = low + (high - low) / 2;
    if (folds[mid].codepoint < codepoint) low = mid + 1;
    else high = mid;
  }
  return low < sizeof(folds) / sizeof(folds[0]) && folds[low].codepoint == codepoint ? folds[low].text : nullptr;
}
